function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  if (!/[A-Z]/.test(str)) {
    return str;
  }

  // First pass: handle transitions between lowercase/digit and uppercase
  // Insert underscore where needed without lowercasing yet
  let result = str.replace(/([a-z0-9])([A-Z])/g, '$1_$2');

  // Second pass: handle acronym boundaries (uppercase followed by uppercase then lowercase)
  // e.g., "XML" -> "X_M_L" when followed by lowercase, becomes "xml_" after lowercasing
  // We need to insert before the last uppercase of a sequence if followed by lowercase
  result = result.replace(/([A-Z]+)([A-Z][a-z])/g, '$1_$2');

  // Now convert to lowercase
  return result.toLowerCase();
}

module.exports = { camelToSnake };
