function isValidCardNumber(input) {
  if (typeof input !== 'string') {
    return false;
  }

  // Check for invalid characters (anything not digit, space, or hyphen)
  if (/[^0-9 -]/.test(input)) {
    return false;
  }

  // Remove spaces and hyphens
  const cleaned = input.replace(/[^0-9]/g, '');

  // Check length
  const len = cleaned.length;
  if (len < 12 || len > 19) {
    return false;
  }

  // Luhn algorithm
  let sum = 0;
  for (let i = 0; i < len; i++) {
    let digit = parseInt(cleaned.charAt(i), 10);

    // If from right, double every second digit (indices len-2, len-4, etc.)
    // If len is odd, we double indices len-2, len-4... which corresponds to i being even (0, 2, ...) from right?
    // Let's use the rule: starting from the right, double every second digit.
    // i goes from 0 to len-1. From right: position = len - 1 - i.
    // If (len - 1 - i) is odd (1, 3, 5...), then it's a "second digit" from the right (2nd, 4th...).

    if ((len - 1 - i) % 2 === 1) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
  }

  return sum % 10 === 0;
}

