  const nodes = new Set();
  const dependencies = {};

  // Collect all nodes and dependencies (deduplicate)
  for (const node of Object.keys(graph)) {
    nodes.add(node);
    if (!dependencies[node]) {
      dependencies[node] = new Set();
    }
    for (const dep of graph[node]) {
      nodes.add(dep);
      dependencies[node].add(dep);
    }
  }

  // Initialize in-degree count for all nodes
  const inDegree = new Map();
  for (const node of nodes) {
    inDegree.set(node, 0);
  }
  for (const node of nodes) {
    for (const dep of dependencies[node]) {
      // We are counting how many dependencies each node has
      // But the logic below uses a different approach: we will decrement in-degree
      // as we satisfy dependencies. Let's restructure:
      // inDegree[node] = number of unsatisfied dependencies for node
    }
  }

  // Recompute in-degree properly: for each node, count how many dependencies it has
  const inDegreeFinal = new Map();
  for (const node of nodes) {
    let count = 0;
    for (const dep of dependencies[node]) {
      count++;
    }
    inDegreeFinal.set(node, count);
  }

  const result = [];
  const processed = new Set();

  // At each step, find all nodes with in-degree 0 (all dependencies satisfied)
  while (result.length < nodes.size) {
