from datetime import date, datetime
from typing import Iterable

def business_days(start: str, end: str, holidays: Iterable[str] = ()) -> int:
    """
    Count working days (Monday-Friday, excluding holidays) in the half-open range [start, end).

    Parameters:
        start (str): ISO date string "YYYY-MM-DD", inclusive start
        end (str): ISO date string "YYYY-MM-DD", exclusive end
        holidays (Iterable[str]): Iterable of ISO date strings representing holidays

    Returns:
        int: Number of business days in the range

    Raises:
        ValueError: If end < start or if any date string is invalid
    """
    def parse_date(date_str: str) -> date:
        try:
            return datetime.strptime(date_str, "%Y-%m-%d").date()
        except ValueError as e:
            raise ValueError(f"Invalid date string: {date_str}") from e

    start_date = parse_date(start)
    end_date = parse_date(end)

    if end_date <= start_date:
        raise ValueError("end must be after start")

    holiday_set = set()
    for h in holidays:
        try:
            holiday_set.add(parse_date(h))
        except ValueError:
            raise ValueError(f"Invalid holiday string: {h}") from None

    count = 0
    current = start_date
    while current < end_date:
        if current.weekday() < 5 and current not in holiday_set:
            count += 1
        current += __import__('datetime').timedelta(days=1)

    return count

