def flatten(obj, sep="."):
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    def _flatten(current_obj, prefix):
        if not isinstance(current_obj, (dict, list)):
            return {prefix: current_obj}

        result = {}
        if isinstance(current_obj, dict):
            for k, v in current_obj.items():
                new_prefix = f"{prefix}{sep}{k}"
                result.update(_flatten(v, new_prefix))
        elif isinstance(current_obj, list):
            for i, v in enumerate(current_obj):
                new_prefix = f"{prefix}{sep}{i}"
                result.update(_flatten(v, new_prefix))
        return result

    # Handle empty dict case
    if not obj:
        return {}

    # Start recursion with empty prefix logic
    # Since the root is a dict, we iterate over its items directly
    result = {}
    for k, v in obj.items():
        result.update(_flatten(v, str(k)))
    return result
