function topoSort(graph) {
  if (typeof graph !== 'object' || graph === null || Array.isArray(graph)) {
    throw new Error('graph must be a plain object');
  }

  const taskSet = new Set();

  // Collect all task names: keys and all dependency values
  for (const [task, deps] of Object.entries(graph)) {
    if (!Array.isArray(deps)) {
      throw new Error('graph values must be arrays');
    }
    taskSet.add(task);
    for (const dep of deps) {
      if (typeof dep !== 'string') {
        throw new Error('dependency names must be strings');
      }
      taskSet.add(dep);
    }
  }

  // Build adjacency: for each task, track its remaining dependencies
  const remainingDeps = new Map();
  for (const task of taskSet) {
    remainingDeps.set(task, new Set());
  }

  for (const [task, deps] of Object.entries(graph)) {
    for (const dep of deps) {
      remainingDeps.get(task).add(dep);
    }
  }

  const result = [];
  const visited = new Set();

  while (result.length + visited.size < taskSet.size) {
    // Find all tasks with no remaining dependencies that haven't been visited
    let candidates = [];
    for (const task of taskSet) {
      if (visited.has(task)) continue;
      const deps = remainingDeps.get(task);
      if (deps.size === 0) {
        candidates.push(task);
      }
    }

    if (candidates.length === 0) {
      throw new Error('cycle detected in dependencies');
    }

    // Sort candidates lexicographically and pick the first one
    candidates.sort();
    const nextTask = candidates[0];

    // Mark as visited and add to result
    visited.add(nextTask);
    result.push(nextTask);

    // Remove this task from all dependency lists
    for (const task of taskSet) {
      if (!visited.has(task) && remainingDeps.get(task).has(nextTask)) {
        remainingDeps.get(task).delete(nextTask);
      }
    }
  }

  return result;
}

