  if (typeof graph !== 'object' || graph === null || Array.isArray(graph)) {
    throw new TypeError('graph must be a plain object');
  }

  const tasks = new Set();

  // Collect all task names: keys and any names found in dependency lists
  for (const task of Object.keys(graph)) {
    tasks.add(task);
  }

  for (const deps of Object.values(graph)) {
    if (!Array.isArray(deps)) {
      throw new TypeError('Dependency values must be arrays');
    }
    for (const dep of deps) {
      if (typeof dep !== 'string') {
        throw new TypeError('Dependency names must be strings');
      }
      tasks.add(dep);
    }
  }

  // Build adjacency: for each task, store its dependencies (only the ones that are in tasks)
  const dependencies = new Map();
  for (const task of tasks) {
    dependencies.set(task, new Set());
  }

  for (const [task, deps] of Object.entries(graph)) {
    if (!Array.isArray(deps)) {
      throw new TypeError('Dependency values must be arrays');
    }
    const depSet = new Set();
    for (const dep of deps) {
      if (tasks.has(dep)) {
        depSet.add(dep);
      }
    }
    dependencies.set(task, depSet);
  }

  // Kahn's algorithm with a min-heap simulation (using array + sort for simplicity)
  const result = [];
  const inDegree = new Map();
  const adj = new Map();

  // Initialize in-degree and adjacency
  for (const task of tasks) {
    inDegree.set(task, 0);
    adj.set(task, []);
  }

  for (const [task, deps] of dependencies.entries()) {
    for (const dep of deps) {
      adj.get(dep).push(task); // dep -> task (task depends on dep)
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  // Start with tasks that have in-degree 0
  let candidates = [];
  for (const task of tasks) {
    if (inDegree.get(task) === 0) {
      candidates.push(task);
    }
  }

  // Sort candidates to ensure deterministic order
  candidates.sort();

  while (candidates.length > 0) {
    // Pick the smallest task name
    candidates.sort();
    const current = candidates.shift();
    result.push(current);

    // Update neighbors
    for (const neighbor of adj.get(current)) {
      inDegree.set(neighbor, inDegree.get(neighbor) - 1);
      if (inDegree.get(neighbor) === 0) {
        candidates.push(neighbor);
      }
    }
  }

  if (result.length !== tasks.size) {
    throw new Error('Cycle detected');
  }

  return result;
}

