class LRUCache:
    def __init__(self, capacity: int):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an integer")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        self.capacity = capacity
        self._cache = {}  # Maps key to value
        self._order = []  # List of keys in order of recency (LRU at start, MRU at end)

    def _move_to_end(self, key: str) -> None:
        # Move key to end (MRU) if it exists
        if key in self._order:
            self._order.remove(key)
        self._order.append(key)

    def get(self, key, default=None):
        if key not in self._cache:
            return default

        # Mark as most recently used
        self._move_to_end(key)
        return self._cache[key]

    def put(self, key: str, value) -> None:
        # If key exists, update value and move to end
        if key in self._cache:
            self._cache[key] = value
            self._move_to_end(key)
            return

        # Check capacity before adding new item
        if len(self._cache) >= self.capacity:
            # Remove least recently used (first element)
            lru_key = self._order.pop(0)
            del self._cache[lru_key]

        # Add new key
        self._cache[key] = value
        self._order.append(key)

    def __len__(self):
        return len(self._cache)

    def __contains__(self, key):
        return key in self._cache

    def keys(self):
        # Return keys from LRU to MRU
        return list(self._order)
