function topoSort(graph) {
  if (typeof graph !== 'object' || graph === null || Array.isArray(graph)) {
    throw new TypeError('graph must be an object');
  }

  // Build a set of all tasks (keys + values in dependency lists)
  const allTasks = new Set();
  for (const [task, deps] of Object.entries(graph)) {
    allTasks.add(task);
    if (!Array.isArray(deps)) {
      throw new TypeError('Dependency list must be an array');
    }
    for (const dep of deps) {
      if (typeof dep !== 'string') {
        throw new TypeError('Dependency names must be strings');
      }
      allTasks.add(dep);
    }
  }

  // Build adjacency list and in-degree count for all tasks
  const inDegree = new Map();
  const adj = new Map();

  for (const task of allTasks) {
    inDegree.set(task, 0);
    adj.set(task, []);
  }

  for (const [task, deps] of Object.entries(graph)) {
    // Deduplicate and validate dependencies
    const uniqueDeps = new Set(deps);
    for (const dep of uniqueDeps) {
      if (!allTasks.has(dep)) {
        throw new Error(`Unknown dependency: ${dep}`);
      }
      // Add edge: dep -> task (since dep must come before task)
      adj.get(dep).push(task);
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  // Kahn's algorithm with priority selection
  const result = [];
  const ready = [];

  // Initialize ready queue with tasks having in-degree 0
  for (const task of allTasks) {
    if (inDegree.get(task) === 0) {
      ready.push(task);
    }
  }

  // Sort ready queue to ensure deterministic order from the start
  ready.sort();

  let head = 0;
  while (head < ready.length) {
    // Pick the smallest task from the ready queue
    const task = ready[head];
    head++;

    result.push(task);

    // Reduce in-degree for neighbors
    for (const neighbor of adj.get(task)) {
      inDegree.set(neighbor, inDegree.get(neighbor) - 1);
      if (inDegree.get(neighbor) === 0) {
        ready.push(neighbor);
      }
    }

    // Sort the remaining ready queue to maintain order property
    // This ensures we always pick the smallest available task
    ready.sort();
  }

  if (result.length !== allTasks.size) {
    throw new Error('Cycle detected in graph');
  }

  return result;
}

