def business_days(start: str, end: str, holidays: Iterable[str] = ()) -> int:
    """
    Count working days in a half-open range [start, end).

    - start and end are ISO date strings "YYYY-MM-DD"
    - holidays is an iterable of ISO date strings
    - Only Monday-Friday are counted
    - Holidays are excluded
    - Range is half-open: start <= d < end
    - Raises ValueError if end < start or if any date string is invalid
    """
    def parse_date(s: str) -> date:
        try:
            return datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            raise ValueError(f"Invalid date string: {s}")

    start_date = parse_date(start)
    end_date = parse_date(end)

    if end_date < start_date:
        raise ValueError("end must be greater than or equal to start")

    # Parse and validate holidays
    holiday_set = set()
    for h in holidays:
        if not h:
            raise ValueError("Holiday cannot be empty")
        holiday_set.add(parse_date(h))

    if start_date == end_date:
        return 0

    count = 0
    current = start_date

    while current < end_date:
        # Check if weekday (0=Monday, 4=Friday)
        if current.weekday() < 5:
            if current not in holiday_set:
                count += 1
        current += timedelta(days=1)

    return count

