function topoSort(graph) {
  if (typeof graph !== 'object' || graph === null || Array.isArray(graph)) {
    throw new Error('Input must be an object');
  }

  const tasks = new Set();

  // Collect all task names: keys and all dependency values
  for (const [task, deps] of Object.entries(graph)) {
    if (!Array.isArray(deps)) {
      throw new Error('Each dependency list must be an array');
    }
    tasks.add(task);
    for (const dep of deps) {
      tasks.add(dep);
    }
  }

  // Build adjacency: for each task, store the set of tasks that depend on it
  // and track in-degrees (number of dependencies not yet placed).
  const inDegree = new Map();
  const dependents = new Map();

  for (const task of tasks) {
    inDegree.set(task, 0);
    dependents.set(task, new Set());
  }

  for (const [task, deps] of Object.entries(graph)) {
    for (const dep of deps) {
      // dep must come before task
      // task depends on dep
      if (!tasks.has(dep)) {
        throw new Error('Invalid dependency reference');
      }
      inDegree.set(task, inDegree.get(task) + 1);
      dependents.get(dep).add(task);
    }
  }

  // Find all tasks with in-degree 0 (no unplaced dependencies)
  const queue = [];
  for (const task of tasks) {
    if (inDegree.get(task) === 0) {
      queue.push(task);
    }
  }

  const result = [];

  while (queue.length > 0) {
    // Sort queue to pick the lexicographically smallest available task
    queue.sort();

    const task = queue.shift();
    result.push(task);

    // Decrease in-degree of all tasks that depend on this task
    for (const dependent of dependents.get(task)) {
      inDegree.set(dependent, inDegree.get(dependent) - 1);
      if (inDegree.get(dependent) === 0) {
        queue.push(dependent);
      }
    }
  }

  if (result.length !== tasks.size) {
    throw new Error('cycle detected');
  }

  return result;
}

