  for (const [node, deps] of Object.entries(graph)) {
    for (const dep of new Set(deps)) { // dedupe dependencies
      // dep -> node (dep must come before node)
      adj.get(dep).push(node);
    }
  }

  // Compute in-degrees based on dependencies
  for (const [node, deps] of Object.entries(graph)) {
    const uniqueDeps = [...new Set(deps)];
    inDegree.set(node, uniqueDeps.length);
  }

  // Initialize queue with nodes that have in-degree 0 (no dependencies)
  // Sort them to ensure deterministic behavior
  const ready = [];
  for (const node of nodes) {
    if (inDegree.get(node) === 0) {
      ready.push(node);
    }
  }
