from datetime import date, datetime, timedelta
from typing import Iterable, Set

def business_days(start: str, end: str, holidays: Iterable[str] = ()) -> int:
    """
    Count working days in the half-open range [start, end).

    Dates are ISO format "YYYY-MM-DD". Working days are Monday-Friday excluding holidays.

    Raises:
        ValueError: If dates are invalid or end < start.
    """

    def parse_date(date_str: str) -> date:
        try:
            return datetime.strptime(date_str, "%Y-%m-%d").date()
        except ValueError as e:
            raise ValueError(f"Invalid date string: {date_str}") from e

    start_date = parse_date(start)
    end_date = parse_date(end)

    if end_date <= start_date:
        raise ValueError("end must be later than start")

    # Convert holidays to a set of date objects for O(1) lookup
    holiday_set: Set[date] = set()
    for h in holidays:
        h_date = parse_date(h)
        holiday_set.add(h_date)

    count = 0
    current = start_date

    while current < end_date:
        # Check if it's a weekday (Monday=0, ..., Friday=4)
        if current.weekday() < 5:
            if current not in holiday_set:
                count += 1
        current += timedelta(days=1)

    return count

