function parseQuery(qs) {
  if (typeof qs !== 'string') {
    throw new TypeError('qs must be a string');
  }

  if (qs.length === 0 || qs === '?') {
    return {};
  }

  // Remove leading '?' if present
  if (qs.startsWith('?')) {
    qs = qs.slice(1);
  }

  if (qs.length === 0) {
    return {};
  }

  const result = {};

  const pairs = qs.split('&');

  for (const pair of pairs) {
    // Skip empty pairs (trailing &, multiple &&, etc.)
    if (pair.length === 0) {
      continue;
    }

    // Split at first '='
    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;

    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.slice(0, eqIndex);
      rawValue = pair.slice(eqIndex + 1);
    }

    // Decode key
    const key = decodeURIComponentSafe(rawKey);

    // Skip if decoded key is empty
    if (key === '') {
      continue;
    }

    // Decode value
    const value = decodeURIComponentSafe(rawValue);

    // Handle multiple occurrences
    if (Object.prototype.hasOwnProperty.call(result, key)) {
      const current = result[key];
      if (Array.isArray(current)) {
        current.push(value);
      } else {
        result[key] = [current, value];
      }
    } else {
      result[key] = value;
    }
  }

