    def __init__(self, capacity: int):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an integer")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        self._capacity = capacity
        self._cache = {}  # Maps key to a doubly linked list node
        self._order = []  # Maintains order from least to most recently used

    def _move_to_front(self, key: str):
        # Remove from current position and add to front
        if key in self._order:
            self._order.remove(key)
        self._order.append(key)

    def get(self, key, default=None):
        if key not in self._cache:
            return default
        self._move_to_front(key)
        return self._cache[key]

    def put(self, key, value):
        if key in self._cache:
            # Update value and mark as most recently used
            self._cache[key] = value
            self._move_to_front(key)
        else:
            # Check if capacity is exceeded
            if len(self._cache) >= self._capacity:
                # Remove least recently used key (first in the order list)
                lru_key = self._order.pop(0)
                del self._cache[lru_key]

