function topoSort(graph) {
  const result = [];
  const visited = new Set();
  const inProgress = new Set();
  const allTasks = new Set();

  // Collect all tasks, including those only appearing in dependency lists
  for (const task of Object.keys(graph)) {
    allTasks.add(task);
    if (Array.isArray(graph[task])) {
      for (const dep of graph[task]) {
        allTasks.add(dep);
      }
    }
  }

  // Build a map of dependencies for each task (deduplicated)
  const depsMap = new Map();
  for (const task of allTasks) {
    depsMap.set(task, new Set());
  }

  for (const task of Object.keys(graph)) {
    const deps = graph[task];
    if (Array.isArray(deps)) {
      for (const dep of deps) {
        depsMap.get(task).add(dep);
      }
    }
  }

  // Initialize with tasks that have no dependencies
  const ready = [];
  for (const task of allTasks) {
    const deps = depsMap.get(task);
    if (deps.size === 0) {
      ready.push(task);
    }
  }

  // Sort ready queue to always pick smallest lexicographically
  ready.sort();

  const processed = new Set();

  while (ready.length > 0) {
    // Pick the smallest task
    ready.sort();
    const current = ready.shift();

    if (processed.has(current)) continue;
    if (inProgress.has(current)) {
      throw new Error('cycle detected');
    }

    inProgress.add(current);
    result.push(current);
    processed.add(current);

    // Now find tasks that can be added next
    for (const task of allTasks) {
      if (processed.has(task) || inProgress.has(task)) continue;
      const deps = depsMap.get(task);
      if (deps.size === 0) {
