function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');

  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();

    if (trimmed === '') {
      // Empty part due to consecutive commas or leading/trailing comma
      throw new SyntaxError('malformed part');
    }

    // Check for multiple dashes or invalid characters
    const dashCount = (trimmed.match(/-/g) || []).length;

    if (dashCount === 0) {
      // Single number case
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError('malformed part');
      }
      const num = parseInt(trimmed, 10);
      if (Number.isNaN(num)) {
        throw new SyntaxError('malformed part');
      }
      result.add(num);
    } else if (dashCount === 1) {
      // Range case: lo-hi
      const [loStr, hiStr] = trimmed.split('-');

      // Check for empty lo or hi (e.g., "1-", "-5")
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('malformed part');
      }

      // Validate numbers: must be non-negative integers only
      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('malformed part');
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError('start greater than end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      // More than one dash
      throw new SyntaxError('malformed part');
    }
  }

  const sorted = Array.from(result);
  sorted.sort((a, b) => a - b);

  return sorted;
}

module.exports = { expandRanges };
