def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    result = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            break

        if line[i] == '"':
            # Start of quoted field
            j = i + 1
            while j < n:
                if line[j] == '"':
                    # Check for doubled quote (escaped quote)
                    if j + 1 < n and line[j+1] == '"':
                        j += 2
                        continue
                    else:
                        # End of quoted field
                        # The value inside is everything between i+1 and j, with "" replaced by "
                        field_content = line[i+1:j]
                        # Process escaped quotes
                        field_value = field_content.replace('""', '"')
                        result.append(field_value)
                        i = j + 1
                        # After closing quote, next char must be comma or end of line
                        if i < n and line[i] != ',':
                            raise ValueError("After closing quote, expected comma or end of line")
                        break
                else:
                    j += 1
            else:
                # Quoted field never closed
                raise ValueError("Unclosed quoted field")
        elif line[i] == ',':
            # Empty field between commas or at start/end
            result.append("")
            i += 1
        else:
            # Unquoted field: read until comma or end
            j = i
            while j < n and line[j] != ',':
                j += 1

            field_value = line[i:j]
            result.append(field_value)
            i = j

    return result
