def rle_encode(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    if any(c.isdigit() for c in s):
        raise ValueError("Input must not contain digit characters")

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{count}{current_char}")
            current_char = char
            count = 1

    result.append(f"{count}{current_char}")
    return "".join(result)


def rle_decode(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    result = []
    i = 0

    while i < len(s):
        if s[i].isdigit():
            # Read the entire count (may have multiple digits)
            count_str = s[i]
            i += 1

            # Continue reading digits
            while i < len(s) and s[i].isdigit():
                count_str += s[i]
                i += 1

            # Parse count
            count = int(count_str)

            # Check for count of zero
            if count == 0:
                raise ValueError("Count cannot be zero")

            # Check for missing character after count
            if i >= len(s):
                raise ValueError("Missing character after count")

            # The next character must not be a digit (it's the character to repeat)
            char = s[i]
            i += 1

            result.append(char * count)
        else:
            # Non-digit character found where count is expected
            raise ValueError("Missing count")

    return "".join(result)
