      const dashIndex = trimmed.indexOf('-');
      const loStr = trimmed.slice(0, dashIndex);
      const hiStr = trimmed.slice(dashIndex + 1);

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('malformed part: missing start or end of range');
      }

      if (!/^[0-9]+$/.test(loStr) || !/^[0-9]+$/.test(hiStr)) {
        throw new SyntaxError('malformed part: invalid numbers in range');
      }

