    if (!this._listeners[event]) {
      this._listeners[event] = [];
    }
    this._listeners[event].push({ fn, once: false });
    return this;
  }

  once(event, fn) {
    this._validateFn(fn);
    if (!this._listeners[event]) {
      this._listeners[event] = [];
    }
    this._listeners[event].push({ fn, once: true });
    return this;
