      const hiStr = trimmed.slice(dashIndex + 1);

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError(`Invalid page range: "${trimmed}"`);
      }

      const lo = Number(loStr);
      const hi = Number(hiStr);

      if (!Number.isFinite(lo) || !Number.isFinite(hi)) {
        throw new SyntaxError(`Invalid page range: "${trimmed}"`);
      }

      if (lo > hi) {
        throw new RangeError(`Invalid page range: start greater than end in "${trimmed}"`);
      }

      for (let n = lo; n <= hi; n++) {
