def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if any(c.isdigit() for c in s):
        raise ValueError("Input must not contain any digit character")

    if not s:
        return ""

    result = []
    count = 1
    prev = s[0]

    for i in range(1, len(s)):
        if s[i] == prev:
            count += 1
        else:
            result.append(f"{count}{prev}")
            prev = s[i]
            count = 1

    result.append(f"{count}{prev}")
    return "".join(result)


def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    result = []
    i = 0

    while i < len(s):
        # Extract digits for the count
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1

        if j == i:
            raise ValueError("Missing count (no digits found)")

        count_str = s[i:j]
        count = int(count_str)

        if count == 0:
            raise ValueError("Count must be at least 1")

        # The next character must be a non-digit
        if j >= len(s):
            raise ValueError("Trailing digits with no character")

        char = s[j]
        if char.isdigit():
            raise ValueError("Character must be a non-digit")

        result.append(char * count)
        i = j + 1

    return "".join(result)
