function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();

    if (trimmed === '') {
      throw new SyntaxError('malformed part');
    }

    const dashIndex = trimmed.indexOf('-');

    if (dashIndex === -1) {
      // Single number
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError('malformed part');
      }
      result.add(parseInt(trimmed, 10));
    } else if (dashIndex === 0 || dashIndex === trimmed.length - 1) {
      // Range with missing start or end
      throw new SyntaxError('malformed part');
    } else if (trimmed.indexOf('-', dashIndex + 1) !== -1) {
      // More than one dash
      throw new SyntaxError('malformed part');
    } else {
      // Inclusive range lo-hi
      const loStr = trimmed.slice(0, dashIndex);
      const hiStr = trimmed.slice(dashIndex + 1);

      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('malformed part');
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError('start must not exceed end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
