def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            j = i + 1
            content = []
            while j < n:
                if line[j] == '"':
                    if j + 1 < n and line[j + 1] == '"':
                        # Escaped quote
                        content.append('"')
                        j += 2
                    else:
                        # End of quoted field
                        j += 1
                        break
                else:
                    content.append(line[j])
                    j += 1

            if j >= n:
                # Never closed
                raise ValueError("Unclosed quoted field")

            # Check what follows the closing quote
            if j < n:
                if line[j] == ',':
                    i = j + 1
                else:
                    raise ValueError("Invalid character after quoted field")
            else:
                # End of line is allowed
                i = j

            fields.append("".join(content))
        else:
            # Unquoted field
            comma = line.find(',', i)
            if comma == -1:
                # No more commas, take the rest
                fields.append(line[i:])
                break
            else:
                # Take everything up to the comma
                fields.append(line[i:comma])
                i = comma + 1

    return fields
