      if (!/^\d+$/.test(part)) {
        throw new SyntaxError(`malformed part: invalid number "${part}"`);
      }
      result.add(parseInt(part, 10));
    } else if (dashIndex === 0 || dashIndex === part.length - 1 || part.indexOf('-', dashIndex + 1) !== -1) {
      // Leading dash, trailing dash, or multiple dashes
      throw new SyntaxError('malformed part: invalid range format');
    } else {
      // Range case: must have exactly one dash in the middle
      const startStr = part.slice(0, dashIndex);
      const endStr = part.slice(dashIndex + 1);

