        if not s[i].isdigit():
            raise ValueError("Missing count")

        # Read all digits for the count
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1

        if j == i:
            raise ValueError("Missing count")

        count_str = s[i:j]
        count = int(count_str)

        if count == 0:
            raise ValueError("Count must be at least 1")

        if j >= len(s):
            raise ValueError("Missing character after count")

        char = s[j]
        if char.isdigit():
            raise ValueError("Character cannot be a digit")

        result.append(char * count)
        i = j + 1

    return "".join(result)
