function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();

    if (trimmed === '') {
      throw new SyntaxError('malformed part: empty part');
    }

    if (!/^-?[0-9]+(-[0-9]+)?$/.test(trimmed)) {
      throw new SyntaxError(`malformed part: ${trimmed}`);
    }

    const dashIndex = trimmed.indexOf('-');

    if (dashIndex === -1) {
      // Single number
      const num = Number(trimmed);
      if (Number.isNaN(num)) {
        throw new SyntaxError(`malformed part: ${trimmed}`);
      }
      result.add(num);
    } else if (dashIndex === 0 && trimmed.length === 1) {
      // Just a dash, e.g. "-"
      throw new SyntaxError(`malformed part: ${trimmed}`);
    } else if (trimmed.endsWith('-')) {
      // Missing end, e.g. "1-"
      throw new SyntaxError(`malformed part: ${trimmed}`);
    } else if (trimmed.includes('-', dashIndex + 1)) {
      // More than one dash, e.g. "1-2-3"
      throw new SyntaxError(`malformed part: ${trimmed}`);
    } else {
      // Valid range "lo-hi"
      const loStr = trimmed.substring(0, dashIndex);
      const hiStr = trimmed.substring(dashIndex + 1);

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError(`malformed part: ${trimmed}`);
      }

      const lo = Number(loStr);
      const hi = Number(hiStr);

      if (Number.isNaN(lo) || Number.isNaN(hi)) {
        throw new SyntaxError(`malformed part: ${trimmed}`);
      }

      if (lo > hi) {
        throw new RangeError(`range start is greater than end: ${trimmed}`);
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

