        return []

    num_rows = len(matrix)
    if not all(isinstance(row, list) for row in matrix):
        raise ValueError("Each row must be a list")

    row_lengths = [len(row) for row in matrix]
    if not row_lengths:
        return []

    first_len = row_lengths[0]
    if any(length != first_len for length in row_lengths):
        raise ValueError("All rows must have the same length")

    if first_len == 0:
        return []

    result = []
    top, bottom = 0, num_rows - 1
    left, right = 0, first_len - 1

    while top <= bottom and left <= right:
        # Traverse from left to right along the top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # Traverse from top to bottom along the right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        # Traverse from right to left along the bottom row, if there are rows left
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        # Traverse from bottom to top along the left column, if there are columns left
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result
