def wrap_text(text, width):
    if not isinstance(width, int):
        raise TypeError("width must be an integer")
    if width < 1:
        raise ValueError("width must be at least 1")

    if not isinstance(text, str):
        raise TypeError("text must be a string")

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_len = 0

    for word in words:
        # Length needed if we add this word: existing length + 1 (space) + word length
        # If current_line is empty, we don't need the space
        needed = current_len + (1 if current_len > 0 else 0) + len(word)

        if needed <= width:
            current_line.append(word)
            current_len = current_len + (1 if current_len > 0 else 0) + len(word)
        else:
            lines.append(" ".join(current_line))
            current_line = [word]
            current_len = len(word)

    if current_line:
        lines.append(" ".join(current_line))

    return lines
