  let maxColWidth = 0;
  for (const row of processedRows) {
    if (row.length > maxColWidth) {
      maxColWidth = row.length;
    }
  }

  for (const row of processedRows) {
    while (row.length < maxColWidth) {
      row.push('');
    }
  }

  const lineCount = processedRows.length;
  const colCount = maxColWidth;
  const colWidths = new Array(colCount).fill(0);

  for (let c = 0; c < colCount; c++) {
    let maxLen = 0;
    for (let r = 0; r < lineCount; r++) {
      const len = processedRows[r][c].length;
      if (len > maxLen) {
        maxLen = len;
      }
    }
    colWidths[c] = maxLen;
  }

  const lines = [];
  for (const row of processedRows) {
    const parts = [];
    for (let c = 0; c < colCount; c++) {
