def search_rotated(nums, target):
    n = len(nums)
    if n == 0:
        return -1

    left, right = 0, n - 1

    while left <= right:
        mid = (left + right) // 2
        mid_val = nums[mid]

        if mid_val == target:
            return mid

        # Determine which side is sorted
        if nums[left] <= mid_val:
            # Left half is sorted
            if nums[left] <= target < mid_val:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right half is sorted
            if mid_val < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1
