  const match = dateStr.match(dateRegex);
  if (!match) {
    throw new RangeError('dateStr has wrong shape');
  }

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  if (year < 1 || year > 9999) {
    throw new RangeError('Year out of range');
  }

  // Validate calendar date: use Date constructor carefully to catch invalid dates
  // Construct a Date in UTC by using the offset of 0 (UTC) via Date.UTC
  // Date.UTC returns milliseconds; we can then reconstruct to check validity
  const ms = Date.UTC(year, month - 1, day);
  if (ms === NaN) {
    throw new RangeError('Not a real calendar date');
  }

  const d = new Date(ms);
  if (d.getFullYear() !== year || d.getMonth() !== month - 1 || d.getDate() !== day) {
    throw new RangeError('Not a real calendar date');
  }

  // Add days using UTC arithmetic
  const totalDaysToAdd = days;
  const baseDate = new Date(d); // copy
  baseDate.setUTCDate(baseDate.getUTCDate() + totalDaysToAdd);

  const newYear = baseDate.getUTCFullYear();
  const newMonth = baseDate.getUTCMonth() + 1;
  const newDay = baseDate.getUTCDate();

  if (newYear < 1 || newYear > 9999) {
    throw new RangeError('Resulting year out of range');
  }

  const pad = (n, len) => String(n).padStart(len, '0');

  return `${pad(newYear, 4)}-${pad(newMonth, 2)}-${pad(newDay, 2)}`;
}

