function formatTable(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError("rows must be an array");
  }

  for (const row of rows) {
    if (!Array.isArray(row)) {
      throw new TypeError("rows must be an array of arrays");
    }
  }

  if (rows.length === 0) {
    return "";
  }

  // Normalize: convert to strings, treat null/undefined as empty string
  const normalized = rows.map((row) =>
    row.map((cell) => {
      if (cell === null || cell === undefined) {
        return "";
      }
      return String(cell);
    })
  );

  // Calculate max width per column
  const numCols = normalized.reduce((max, row) => Math.max(max, row.length), 0);
  const widths = [];
  for (let i = 0; i < numCols; i++) {
    let maxLen = 0;
    for (const row of normalized) {
      const cell = row[i];
      const len = cell === undefined ? 0 : cell.length;
      if (len > maxLen) maxLen = len;
    }
    widths.push(maxLen);
  }

  const lines = normalized.map((row) => {
    const cells = [];
    for (let i = 0; i < numCols; i++) {
      let cell = row[i];
      if (cell === undefined) {
        cell = "";
      }
      const padLen = widths[i];
      cells.push(cell.padEnd(padLen, " "));
    }
    let line = cells.join(" | ");
    // Remove trailing spaces from the end of the line
