def search_rotated(nums, target):
    n = len(nums)
    if n == 0:
        return -1

    low, high = 0, n - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid

        # Determine which side is sorted
        if nums[low] <= nums[mid]:
            # Left side is sorted
            if nums[low] <= target < nums[mid]:
                high = mid - 1
            else:
                low = mid + 1
        else:
            # Right side is sorted
            if nums[mid] < target <= nums[high]:
                low = mid + 1
            else:
                high = mid - 1

    return -1
