function addDays(dateStr, days) {
  if (typeof days !== 'number' || !Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }

  const regex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateStr.match(regex);
  if (!match) {
    throw new RangeError('dateStr has the wrong shape');
  }

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  if (month < 1 || month > 12) {
    throw new RangeError('date is not a real calendar date');
  }

  // Validate day against month and leap year
  const daysInMonth = getDaysInMonth(year, month);
  if (day < 1 || day > daysInMonth) {
    throw new RangeError('date is not a real calendar date');
  }

  // Validate year range for input
  if (year < 1 || year > 9999) {
    throw new RangeError('year of input is outside 0001..9999');
  }

  // Create a UTC date object. Using Date.UTC to avoid local timezone issues.
  const date = new Date(Date.UTC(year, month - 1, day));

  // Add days
  date.setDate(date.getDate() + days);

  // Extract components from the UTC date
  const newYear = date.getUTCFullYear();
  const newMonth = date.getUTCMonth() + 1;
  const newDay = date.getUTCDate();

  // Validate resulting year range
  if (newYear < 1 || newYear > 9999) {
    throw new RangeError('year of the result is outside 0001..9999');
  }

  // Format output as YYYY-MM-DD
  const y = String(newYear).padStart(4, '0');
  const m = String(newMonth).padStart(2, '0');
  const d = String(newDay).padStart(2, '0');

  return `${y}-${m}-${d}`;
}

function getDaysInMonth(year, month) {
  if (month === 1 || month === 3 || month === 5 || month === 7 || month === 8 || month === 10 || month === 12) {
    return 31;
  }
  if (month === 4 || month === 6 || month === 9 || month === 11) {
    return 30;
  }
  if (month === 2) {
    // Leap year check: divisible by 4, unless divisible by 100 but not by 400
    const isLeap = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
    return isLeap ? 29 : 28;
  }
  return 0; // Should not happen due to earlier validation
}

