def wrap_text(text, width):
    if not isinstance(width, int):
        raise TypeError("width must be an integer")
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        word_len = len(word)
        if word_len > width:
            # Word longer than width: output current line if any, then the word alone
            if current_line:
                lines.append(" ".join(current_line))
                current_line = []
