    let key;
    if (typeof keyFn === 'function') {
      key = keyFn.apply(this, args);
    } else {
      key = args[0];
    }

    if (cache.has(key)) {
      return cache.get(key);
    }

    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };

  wrapped.clear = function () {
    cache.clear();
  };

  return wrapped;
}

