            # String literal start
            i += 1
            while i < n:
                c = code[i]
                if c == '\\' and i + 1 < n:
                    # Escaped character, skip both
                    i += 2
                elif c == '"':
                    # End of string literal
                    i += 1
                    break
                else:
                    # Any other character inside string, skip
                    i += 1
            else:
                # String never closed
                return False
            continue

        # Process bracket characters
        if char == '(':
            stack.append(')')
        elif char == '[':
            stack.append(']')
        elif char == '{':
            stack.append('}')
        elif char == ')':
