    start = None
    end = None
    count_s = 0
    count_e = 0

    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch not in allowed_chars:
                raise ValueError(f"Invalid character '{ch}' in grid")
            if ch == 'S':
                count_s += 1
                start = (r, c)
            elif ch == 'E':
                count_e += 1
                end = (r, c)

    if count_s != 1:
        raise ValueError("There must be exactly one 'S'")
    if count_e != 1:
        raise ValueError("There must be exactly one 'E'")

    if start is None or end is None:
        return -1

    from collections import deque

    queue = deque([(start, 0)])
    visited = {start}

    while queue:
        (r, c), dist = queue.popleft()

        if (r, c) == end:
            return dist

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < row_len:
                if (nr, nc) not in visited:
                    cell = grid[nr][nc]
                    if cell == '.' or cell == 'E':
                        visited.add((nr, nc))
                        queue.append(((nr, nc), dist + 1))

    return -1
