    # Adjust month to be within 1..12
    new_month = ((base_date.month + n - 1) % 12) + 1

    # Calculate day clamping
    # First, create a tentative date with the original day
    try:
        tentative_date = date(new_year, new_month, base_date.day)
    except ValueError:
        # The day doesn't exist in this month, clamp to last day of month
        if new_month in (1, 3, 5, 7, 8, 10, 12):
            last_day = 31
        elif new_month in (4, 6, 9, 11):
            last_day = 30
        elif new_month == 2:
