            if (new_year % 4 == 0 and new_year % 100 != 0) or (new_year % 400 == 0):
                last_day = 29
            else:
                last_day = 28
        else:
            last_day = 31

        tentative_date = date(new_year, new_month, last_day)

    # Validate year range again after adjustment
    if not (1 <= tentative_date.year <= 9999):
