def maze_steps(grid):
    """
    Returns the length of the shortest path through a maze, or -1 if unreachable.

    Raises:
        ValueError: If rows are not equal length, invalid characters present, or
                    if there isn't exactly one 'S' and one 'E'.
    """
    if not grid:
        raise ValueError("Grid cannot be empty")

    # Validate row lengths
    row_len = len(grid[0])
    for row in grid:
        if len(row) != row_len:
            raise ValueError("All rows must be of equal length")

    # Validate characters and locate S and E
    start_pos = None
    end_pos = None
    valid_chars = {'.', '#', 'S', 'E'}

    for r_idx, row in enumerate(grid):
        for c_idx, char in enumerate(row):
            if char not in valid_chars:
                raise ValueError(f"Invalid character '{char}' found in grid")
            if char == 'S':
                if start_pos is not None:
                    raise ValueError("There must be exactly one 'S'")
                start_pos = (r_idx, c_idx)
            elif char == 'E':
                if end_pos is not None:
                    raise ValueError("There must be exactly one 'E'")
                end_pos = (r_idx, c_idx)

    if start_pos is None or end_pos is None:
        raise ValueError("There must be exactly one 'S' and one 'E'")

    # BFS to find shortest path
    queue = [(start_pos, 0)]
    visited = {start_pos}

    while queue:
        (r, c), steps = queue.pop(0)

        if (r, c) == end_pos:
            return steps

        # Check neighbors (up, down, left, right)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc

            if 0 <= nr < row_len and 0 <= nc < len(grid[0]):
                if (nr, nc) not in visited:
                    cell = grid[nr][nc]
                    if cell in ('.', 'S', 'E'):
                        visited.add((nr, nc))
                        queue.append(((nr, nc), steps + 1))

    return -1
