function isValidDate(dateStr) {
  if (typeof dateStr !== 'string') return false;
  const parts = dateStr.split('-');
  if (parts.length !== 3) return false;
  const year = parseInt(parts[0], 10);
  const month = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);

  if (isNaN(year) || isNaN(month) || isNaN(day)) return false;
  if (year < 1 || year > 9999) return false;
  if (month < 1 || month > 12) return false;
  if (day < 1 || day > 31) return false;

  // Check if the date is valid for the specific month and year
  const date = new Date(Date.UTC(year, month - 1, day));
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() + 1 !== month ||
    date.getUTCDate() !== day
  ) {
    return false;
  }

  return true;
}

function ageOn(birth, on) {
  if (!isValidDate(birth)) {
    throw new RangeError('Invalid birth date');
  }
  if (!isValidDate(on)) {
    throw new RangeError('Invalid on date');
  }

  const birthDate = new Date(Date.UTC(
    parseInt(birth.slice(0, 4), 10),
    parseInt(birth.slice(5, 7), 10) - 1,
    parseInt(birth.slice(8, 10), 10)
  ));

  const onDate = new Date(Date.UTC(
    parseInt(on.slice(0, 4), 10),
    parseInt(on.slice(5, 7), 10) - 1,
    parseInt(on.slice(8, 10), 10)
  ));

  if (onDate < birthDate) {
    throw new RangeError('on must not be earlier than birth');
  }

  let age = onDate.getFullYear() - birthDate.getFullYear();

  // Adjust if the birthday hasn't occurred yet in the current year
  const birthMonth = birthDate.getUTCMonth() + 1;
  const birthDay = birthDate.getUTCDate();
  const currentMonth = onDate.getUTCMonth() + 1;
  const currentDay = onDate.getUTCDate();

  if (currentMonth < birthMonth || (currentMonth === birthMonth && currentDay < birthDay)) {
    age--;
  }

  return age;
}

