from collections import deque

def maze_steps(grid):
    if not grid:
        raise ValueError("grid must not be empty")

    row_len = len(grid[0])
    for row in grid:
        if len(row) != row_len:
            raise ValueError("all rows must be of equal length")

    allowed_chars = {'.', 'S', 'E', '#'}
    for row in grid:
        for ch in row:
            if ch not in allowed_chars:
                raise ValueError(f"invalid character '{ch}' found in grid")

    start = None
    end = None
    count_s = 0
    count_e = 0

    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == 'S':
                start = (r, c)
                count_s += 1
            elif ch == 'E':
                end = (r, c)
                count_e += 1

    if count_s != 1 or count_e != 1:
        raise ValueError("grid must contain exactly one 'S' and exactly one 'E'")

    if start is None or end is None:
        raise ValueError("grid must contain exactly one 'S' and exactly one 'E'")

    # BFS
    queue = deque([(start, 0)])
    visited = set([start])

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        (r, c), dist = queue.popleft()

        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if (nr, nc) not in visited:
                    cell = grid[nr][nc]
                    if cell in {'.', 'S', 'E'}:
                        visited.add((nr, nc))
                        queue.append(((nr, nc), dist + 1))

    return -1
