function parseDate(str) {
  if (typeof str !== 'string') throw new RangeError('Input must be a string');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(str)) throw new RangeError('Invalid date format');

  const [yearStr, monthStr, dayStr] = str.split('-').map(Number);
  const date = new Date(Date.UTC(yearStr, monthStr - 1, dayStr));

  if (date.getUTCFullYear() !== yearStr || date.getUTCMonth() + 1 !== monthStr || date.getUTCDate() !== dayStr) {
    throw new RangeError('Invalid date');
  }

  return date;
}

function ageOn(birthStr, onStr) {
  const birthDate = parseDate(birthStr);
  const onDate = parseDate(onStr);

  if (onDate < birthDate) {
    throw new RangeError('on must not be earlier than birth');
  }

  let age = onDate.getUTCFullYear() - birthDate.getUTCFullYear();
  const birthMonth = birthDate.getUTCMonth();
  const birthDay = birthDate.getUTCDate();

  const onMonth = onDate.getUTCMonth();
  const onDay = onDate.getUTCDate();

  if (onMonth < birthMonth || (onMonth === birthMonth && onDay < birthDay)) {
    age--;
  }

  if (age < 0) {
    throw new RangeError('Invalid age result');
  }

  return age;
}

module.exports = { ageOn };
