async function retry(fn, attempts) {
  if (typeof fn !== 'function') {
    throw new TypeError('fn must be a function');
  }
  if (typeof attempts !== 'number' || !Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('attempts must be an integer of at least 1');
  }

  let lastError;

  for (let i = 1; i <= attempts; i++) {
    try {
      const result = fn(i);
      // Handle both synchronous and asynchronous results
      if (result && typeof result.then === 'function') {
        result.catch(() => {
          // This catch is not used for control flow here, we handle the promise
          // in the try/catch below by awaiting.
        });
      }

      const resolved = await result;
      return resolved;
    } catch (err) {
      lastError = err;
      // If this was the last attempt, the error will be thrown after the loop
      if (i === attempts) {
        throw lastError;
      }
      // If not the last attempt, continue to the next attempt
    }
  }

  // This part should technically be unreachable due to the check inside the loop
  // but we include it to satisfy the compiler that the function always returns/rejects
  throw lastError;
}

module.exports = { retry };
