function longestCommonPrefix(strs) {
  if (!Array.isArray(strs)) {
    throw new TypeError("Argument must be an array");
  }

  for (let i = 0; i < strs.length; i++) {
    if (typeof strs[i] !== "string") {
      throw new TypeError("All elements must be strings");
    }
  }

  if (strs.length === 0) {
    return "";
  }

  if (strs.length === 1) {
    return strs[0];
  }

  // Use the first string as a reference, but we must iterate over code points, not code units
  const first = strs[0];
  const codePoints = [...first]; // Splits into Unicode code points correctly

  for (let i = 0; i < codePoints.length; i++) {
    const currentChar = codePoints[i];

    // Check if this character is the same in all other strings (also iterating code points)
    for (let j = 1; j < strs.length; j++) {
      const otherStr = strs[j];
      if (otherStr === "") {
        return "";
      }

      const otherCodePoints = [...otherStr];

      if (i >= otherCodePoints.length || otherCodePoints[i] !== currentChar) {
        return codePoints.slice(0, i).join("");
      }
    }
  }

  return first;
}

module.exports = { longestCommonPrefix };
